-- Per-destination fulfillment state for purchase orders.
CREATE TABLE procurement_deliveries (
    purchase_order_id INTEGER NOT NULL REFERENCES purchase_orders(id),
    destination_index INTEGER NOT NULL CHECK (destination_index >= 0),
    status TEXT NOT NULL DEFAULT 'confirmed' CHECK (status IN (
        'confirmed', 'preparing', 'ready', 'shipped', 'partially_delivered', 'delivered')),
    tracking_reference TEXT,
    updated_by_user_id INTEGER REFERENCES users(id),
    updated_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')),
    PRIMARY KEY (purchase_order_id, destination_index)
);

-- Receipts are evidence: append-only.
CREATE TABLE procurement_receipts (
    id BIGSERIAL PRIMARY KEY,
    purchase_order_id INTEGER NOT NULL REFERENCES purchase_orders(id),
    destination_index INTEGER NOT NULL CHECK (destination_index >= 0),
    kind TEXT NOT NULL CHECK (kind IN ('full', 'partial', 'shortage', 'damaged', 'mismatch')),
    receiver_name TEXT NOT NULL CHECK (length(trim(receiver_name)) BETWEEN 1 AND 200),
    quantities_json TEXT NOT NULL DEFAULT '[]',
    notes TEXT,
    created_by_user_id INTEGER NOT NULL REFERENCES users(id),
    created_at TEXT NOT NULL DEFAULT (to_char(timezone('UTC', now()), 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))
);

CREATE OR REPLACE FUNCTION procurement_receipts_no_update_fn() RETURNS trigger AS $$
BEGIN
    RAISE EXCEPTION 'procurement_receipts is append-only' USING ERRCODE = '23000';
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER procurement_receipts_no_update
BEFORE UPDATE ON procurement_receipts
FOR EACH ROW EXECUTE PROCEDURE procurement_receipts_no_update_fn();

CREATE OR REPLACE FUNCTION procurement_receipts_no_delete_fn() RETURNS trigger AS $$
